theorem segment_integral_pullback (η : HolomorphicOneForm ℂ Y) {p : X} {q : Y}
    {cV : ℂ} {ρV : ℝ} {cY : ℂ} {ρY : ℝ}
    (hV : ball cV ρV ⊆ (chartAt ℂ p).target)
    (hVf : ∀ w ∈ ball cV ρV, f ((chartAt ℂ p).symm w) ∈ (chartAt ℂ q).source)
    (hVB : ∀ w ∈ ball cV ρV, chartMap f p q w ∈ ball cY ρY)
    (hB : ball cY ρY ⊆ (chartAt ℂ q).target) {a b : ℂ}
    (ha : a ∈ ball cV ρV) (hb : b ∈ ball cV ρV) :
    (∫ᶜ x in Path.segment a b, chartForm p (pullbackFormsBundled f hf η) x) =
      ∫ᶜ x in Path.segment (chartMap f p q a) (chartMap f p q b), chartForm q η x

theorem chartCoeff_transition (ω : HolomorphicOneForm ℂ X) {p q : X} {w : ℂ}
    (hw : w ∈ (chartAt ℂ p).target) (hq : (chartAt ℂ p).symm w ∈ (chartAt ℂ q).source) :
    chartCoeff p ω w = deriv (chartMap id p q) w * chartCoeff q ω (chartMap id p q w)

theorem norm_discCoeffs_le {s : ℝ} (hs : s ≤ 3) (ω : HolomorphicOneForm ℂ X) {M : ℝ}
